<script>
(function(){
  var form=document.getElementById('laboratoryOrderForm'),protocol=document.getElementById('laboratoryProtocol'),search=document.getElementById('laboratoryExamSearch'),submit=document.getElementById('laboratorySubmit'),count=document.getElementById('laboratorySelectedCount'),summary=document.getElementById('laboratorySummaryCount'),map={!! json_encode($protocolExamMap) !!},hasConvention={{$hasConvention?'true':'false'}};
  if(!form)return;
  var boxes=[].slice.call(form.querySelectorAll('[data-exam-id]:not(:disabled)'));
  function notify(title,text){var options={icon:'warning',title:title,text:text,confirmButtonText:'Entendido',confirmButtonColor:'#087fb5'};if(typeof window.mostrarSweetAlertV3==='function')return window.mostrarSweetAlertV3(options);if(window.Swal)return window.Swal.fire(options);window.alert(title+'\n'+text);return Promise.resolve();}
  function selected(){return boxes.filter(function(box){return box.checked;});}
  function refresh(){var total=selected().length;count.textContent=total;summary.textContent=total+' seleccionado'+(total===1?'':'s');submit.disabled=!hasConvention||!protocol.value||total===0;}
  function applyProtocol(reset){var ids=(map[protocol.value]||[]).map(String);boxes.forEach(function(box){box.dataset.locked='0';box.closest('.lco-option').classList.remove('is-locked');if(reset)box.checked=false;if(ids.indexOf(String(box.dataset.examId))!==-1){box.checked=true;box.dataset.locked='1';box.closest('.lco-option').classList.add('is-locked');}});refresh();}
  protocol.addEventListener('change',function(){applyProtocol(true);});
  boxes.forEach(function(box){box.addEventListener('change',function(){if(box.dataset.locked==='1'&&!box.checked){box.checked=true;notify('Examen incluido en el protocolo','Para retirarlo debes seleccionar otro protocolo.');}refresh();});});
  [].slice.call(form.querySelectorAll('[data-select-group]')).forEach(function(button){button.addEventListener('click',function(){var group=button.closest('[data-exam-group]'),groupBoxes=[].slice.call(group.querySelectorAll('[data-exam-id]:not(:disabled)')),all=groupBoxes.every(function(box){return box.checked;});groupBoxes.forEach(function(box){if(box.dataset.locked!=='1')box.checked=!all;});refresh();});});
  search.addEventListener('input',function(){var term=search.value.trim().toLowerCase();[].slice.call(form.querySelectorAll('[data-exam-option]')).forEach(function(option){option.style.display=!term||option.dataset.search.indexOf(term)!==-1?'flex':'none';});[].slice.call(form.querySelectorAll('[data-exam-group]')).forEach(function(group){group.style.display=[].slice.call(group.querySelectorAll('[data-exam-option]')).some(function(option){return option.style.display!=='none';})?'block':'none';});});
  form.addEventListener('submit',function(event){if(!protocol.value){event.preventDefault();notify('Selecciona un protocolo','El protocolo es obligatorio para generar la orden.');protocol.focus();return;}if(!selected().length){event.preventDefault();notify('Selecciona los exámenes','Debes incluir al menos un examen disponible.');search.focus();return;}if(!form.checkValidity()){event.preventDefault();form.reportValidity();return;}submit.disabled=true;submit.innerHTML='<i class="fas fa-circle-notch fa-spin mr-1"></i> Generando…';});
  applyProtocol(false);refresh();
})();
</script>
